SINA_SMART["physio1-pulmonary-vascular"] = {"lecture":"physio1-pulmonary-vascular","title":"Pulmonary vascular physiology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-pulmonary-vascular:e0","text":"Pulmonary circulation: whole cardiac output at low pressure (~20/8 mmHg).","topic":"The pulmonary circulation","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-pulmonary-vascular:e1","text":"Airway disease → low V/Q; embolism → high V/Q (dead space); pneumonia → shunt.","topic":"The pulmonary circulation","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-pulmonary-vascular:e4","text":"Local HPV is good: diverts blood to ventilated alveoli, optimises V/Q.","topic":"The pulmonary circulation","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-pulmonary-vascular:e2","text":"Hypoxia constricts pulmonary arterioles (HPV) but dilates systemic ones.","topic":"Hypoxic pulmonary vasoconstriction","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-pulmonary-vascular:e3","text":"Mechanism: hypoxia closes O₂-sensitive K⁺ channels → depolarisation → Ca²⁺ entry.","topic":"Hypoxic pulmonary vasoconstriction","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-pulmonary-vascular:e5","text":"Fetal HPV keeps blood out of the lungs (foramen ovale, ductus).","topic":"Hypoxic pulmonary vasoconstriction","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-pulmonary-vascular:e6","text":"Global chronic hypoxia → pulmonary hypertension (bad).","topic":"Hypoxic pulmonary vasoconstriction","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-pulmonary-vascular:e7","text":"Low alveolar PCO₂ → bronchoconstriction (ventilation follows perfusion).","topic":"Ventilation-perfusion coupling","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1l4fbi1":"a","15env9o":"a","3uigxd":"a","1ddo6yl":"a","xx4uix":"a","1dw8kuy":"a","89ammu":"a","1gs99as":"a","1apqyvt":"a","1svknjd":"a","tjw0pr":"a","hem0un":"a","1gjby05":"a","109krkh":"a","lq28s3":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-pulmonary-vascular:e0":{"s":0,"u":["Pulmonary circulation: whole cardiac output at low pressure (~20/8 mmHg).","The pulmonary circulation receives the whole cardiac output at low pressure (about 20/8 mmHg) and low resistance."],"dp":[]},"physio1-pulmonary-vascular:e1":{"s":0,"u":["Airway disease → low V/Q; embolism → high V/Q (dead space); pneumonia → shunt.","Ventilation-perfusion problems fall into two groups: obstructive airway disease (COPD, asthma: poorly ventilated but perfused alveoli, V/Q low) and pulmonary vascular disease (e.g. pulmonary embolism : ventilated but unperfused alveoli, V/Q high, dead space).","Pneumonia fills alveoli with exudate: blood through them is not oxygenated (shunt)."],"dp":[]},"physio1-pulmonary-vascular:e4":{"s":0,"u":["Local HPV is good: diverts blood to ventilated alveoli, optimises V/Q.","Ventilation-perfusion problems fall into two groups: obstructive airway disease (COPD, asthma: poorly ventilated but perfused alveoli, V/Q low) and pulmonary vascular disease (e.g. pulmonary embolism : ventilated but unperfused alveoli, V/Q high, dead space).","Pneumonia fills alveoli with exudate: blood through them is not oxygenated (shunt)."],"dp":[{"h":"Why giving oxygen can make some COPD patients worse","t":"In advanced COPD, HPV has diverted blood away from the worst-ventilated regions. Giving high concentrations of oxygen raises alveolar PO₂ everywhere, releases that vasoconstriction and sends blood back to poorly ventilated alveoli, worsening V/Q matching; oxygen also unloads CO₂ from haemoglobin (Haldane effect). PaCO₂ can then rise dangerously. That is why oxygen in COPD is titrated to a target saturation (often 88-92%) rather than given at full flow: a direct clinical consequence of hypoxic pulmonary vasoconstriction. Source: the lecture's 'is HPV good or bad?' question and V/Q coupling."}]},"physio1-pulmonary-vascular:e2":{"s":1,"u":["Hypoxia constricts pulmonary arterioles (HPV) but dilates systemic ones.","In the lecture's experiment, hypoxia raises pulmonary artery pressure within minutes while systemic (renal) artery pressure does not rise: systemic vessels dilate in hypoxia, pulmonary vessels constrict.","When alveolar PO₂ falls, the small pulmonary arteries supplying that region constrict : hypoxic pulmonary vasoconstriction (HPV) ."],"dp":[]},"physio1-pulmonary-vascular:e3":{"s":1,"u":["Mechanism: hypoxia closes O₂-sensitive K⁺ channels → depolarisation → Ca²⁺ entry.","The mechanism involves oxygen-sensitive voltage-gated K⁺ channels : hypoxia closes them, the smooth muscle depolarises, voltage-gated Ca²⁺ channels open and the cell contracts (the same logic as K ATP channels in the pancreatic β-cell)."],"dp":[]},"physio1-pulmonary-vascular:e5":{"s":1,"u":["Fetal HPV keeps blood out of the lungs (foramen ovale, ductus).","In the fetus , HPV keeps pulmonary resistance high so blood bypasses the non-breathing lungs through the foramen ovale and ductus arteriosus ; at birth, lung inflation removes it."],"dp":[]},"physio1-pulmonary-vascular:e6":{"s":1,"u":["Global chronic hypoxia → pulmonary hypertension (bad).","When hypoxia is global and chronic (COPD, altitude), widespread HPV raises pulmonary pressure and causes pulmonary hypertension and right heart strain: then it is bad."],"dp":[]},"physio1-pulmonary-vascular:e7":{"s":2,"u":["Low alveolar PCO₂ → bronchoconstriction (ventilation follows perfusion).","Ventilation adjusted to perfusion : reduced blood flow → low alveolar PCO₂ → bronchoconstriction → less air; increased blood flow → high PCO₂ → bronchodilatation → more air.","Perfusion adjusted to ventilation : reduced airflow → low alveolar PO₂ → vasoconstriction → less blood; increased airflow → high PO₂ → vasodilatation → more blood."],"dp":[]}},"meta":{"1l4fbi1":{"a":"recall","vg":"physio1-pulmonary-vascular:e7/recall/1"},"15env9o":{"a":"recall","vg":"physio1-pulmonary-vascular:e2/recall/1"},"3uigxd":{"a":"recall","vg":"physio1-pulmonary-vascular:e5/recall/1"},"1ddo6yl":{"a":"recall","vg":"physio1-pulmonary-vascular:e6/recall/1"},"xx4uix":{"a":"recall","vg":"physio1-pulmonary-vascular:e3/recall/1"},"1dw8kuy":{"a":"recall","vg":"physio1-pulmonary-vascular:e5/recall/2"},"89ammu":{"a":"recall","vg":"physio1-pulmonary-vascular:e4/recall/1"},"1gs99as":{"a":"recall","vg":"physio1-pulmonary-vascular:e4/recall/1"},"1apqyvt":{"a":"recall","vg":"physio1-pulmonary-vascular:e5/recall/3"},"1svknjd":{"a":"recall","vg":"physio1-pulmonary-vascular:e0/recall/1"},"tjw0pr":{"a":"recall","vg":"physio1-pulmonary-vascular:e4/recall/2"},"hem0un":{"a":"recall","vg":"physio1-pulmonary-vascular:e5/recall/4"},"1gjby05":{"a":"recall","vg":"physio1-pulmonary-vascular:e3/recall/2"},"109krkh":{"a":"relationship","vg":"physio1-pulmonary-vascular:e7/relationship/1"},"lq28s3":{"a":"recall","vg":"physio1-pulmonary-vascular:e7/recall/2"}},"explRev":"18ea8527935f"};
